"""Self-contained offline reports and decision workbenches; no runtime network."""
import json,csv,html
from common import ROOT,CREDIT,REST,readcsv
STYLE='''*{box-sizing:border-box}body{margin:0;background:#f6f4ef;color:#242137;font:16px/1.55 system-ui,sans-serif}header{background:#242137;color:#fff;padding:46px max(6vw,20px)}header p{max-width:850px;color:#d2cce8}.eyebrow{font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:#c6b9ed}h1{font-size:clamp(28px,4vw,43px);line-height:1.12;margin:12px 0 18px}h2{font-size:23px;line-height:1.25;margin-top:0}h3{font-size:18px}main{max-width:1180px;margin:auto;padding:26px 20px 50px}.card{background:white;border:1px solid #ddd9e6;border-radius:10px;padding:26px;margin-bottom:22px;min-width:0}.kpis{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:24px 0}.metric{background:#f3effa;border-left:4px solid #71549f;padding:15px;min-width:0}.metric strong{display:block;font-size:clamp(20px,2.4vw,30px);line-height:1.2;overflow-wrap:anywhere}.metric span,.muted{font-size:13px;color:#655d74}.note{border-left:4px solid #be7d29;background:#fff7e9;padding:16px}.badge{display:inline-block;background:#fff0d6;color:#725018;border-radius:20px;padding:4px 10px;font-size:12px;margin-bottom:12px}.controls{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px;margin:20px 0}.controls label{display:block;font-size:13px;font-weight:650;min-width:0}input,select{font:inherit;width:100%;min-width:0;max-width:100%;padding:10px;border:1px solid #a9a0b9;border-radius:5px;background:white;color:#242137;margin-top:6px}.select-bound{min-width:0;max-width:100%;overflow:hidden;padding:2px}.select-bound:focus-within{outline:3px solid #bc8c37;outline-offset:2px}button{font:inherit;padding:11px 17px;border:0;border-radius:5px;background:#65468e;color:white;cursor:pointer;margin:0 8px 10px 0}button.secondary{background:#e7e1f0;color:#242137}a{color:#62418d;text-underline-offset:3px}button:focus-visible,input:focus-visible,a:focus-visible{outline:3px solid #bc8c37;outline-offset:3px}.scroll{max-width:100%;min-width:0;max-height:460px;overflow:auto;overscroll-behavior:contain}th{position:sticky;top:0;z-index:1}table{border-collapse:collapse;width:100%;font-size:13px;white-space:nowrap}th,td{text-align:left;padding:11px;border-bottom:1px solid #e4dfeb}th{background:#f3effa}#status{padding:14px;background:#f3effa;margin:10px 0;overflow-wrap:anywhere}#status[role=alert]{background:#fff0e8;color:#792b18}svg{display:block;max-width:100%;height:auto}.chart-wrap{overflow:auto}footer{font-size:12px;color:#655d74;max-width:1180px;padding:20px;margin:auto}ul{padding-left:22px}li{margin:7px 0}@media(max-width:760px){.controls{grid-template-columns:repeat(2,minmax(0,1fr))}.kpis{grid-template-columns:1fr}.card{padding:19px}header{padding:30px 20px}}@media(max-width:480px){.controls{grid-template-columns:minmax(0,1fr)}main{padding:18px 12px}.card{padding:17px}table{font-size:12px}}'''
JS=r'''
const $=id=>document.getElementById(id), fmt=x=>new Intl.NumberFormat('en-US',{maximumFractionDigits:0}).format(x), money=x=>(x<0?'−':'')+'$'+fmt(Math.abs(x));
let visible=[];const initial=Object.fromEntries([...document.querySelectorAll('input,select')].map(x=>[x.id,x.value]));
function num(id,lo,hi,open=false){const raw=$(id).value.trim(),v=Number(raw);if(!raw||!Number.isFinite(v)||v<lo||v>hi||(open&&v===lo))throw Error($(id).dataset.name+' is missing or outside its allowed range.');return v;}
function status(s,error=false){$('status').textContent=s;$('status').setAttribute('role',error?'alert':'status');}
function draw(rows){visible=rows;const q=$('search').value.toLowerCase();const a=rows.filter(r=>Object.values(r).join(' ').toLowerCase().includes(q));$('row-count').textContent=a.length+' matching evidence rows';const tb=$('evidence-body');tb.replaceChildren();for(const row of a){const tr=document.createElement('tr');for(const x of Object.values(row)){const td=document.createElement('td');td.textContent=typeof x==='number'?(Number.isInteger(x)?fmt(x):x.toFixed(4)):(x===null?'Unavailable':x);tr.append(td);}tb.append(tr);}if(!a.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=8;td.textContent='No matching evidence. Clear the search to recover.';tr.append(td);tb.append(tr);}}
function calculate(){try{if(DATA.kind==='credit')credit();else restaurant();}catch(e){status(e.message,true);$('result-value').textContent='Unavailable';$('result-detail').textContent='Correct the inputs and calculate again. No stale result is retained.';}}
function credit(){const threshold=num('threshold',.05,.95),cost=num('fncost',1,20),start=$('start').value,end=$('end').value;if(!/^\d{4}-\d{2}$/.test(start)||!/^\d{4}-\d{2}$/.test(end)||start>end||start<'2008-01'||end>'2023-12')throw Error('Choose an ordered evaluation window within 2008-01 to 2023-12.');if(!Array.isArray(DATA.rows)||!DATA.rows.length)throw Error('Pinned prediction evidence is missing.');const rows=DATA.rows.filter(r=>r.date.slice(0,7)>=start&&r.date.slice(0,7)<=end);if(!rows.length)throw Error('No observations in this window.');let tp=0,fp=0,fn=0,tn=0,loss=0;const key=$('model').value;for(const r of rows){const p=Number(r[key]),y=Number(r.y);if(!Number.isFinite(p)||p<0||p>1)throw Error('Invalid pinned probability evidence.');loss+=(p-y)**2;if(p>=threshold){if(y)tp++;else fp++;}else{if(y)fn++;else tn++;}}$('result-value').textContent=(loss/rows.length).toFixed(4);$('result-detail').textContent=`${rows.length} months · TP ${tp}, FP ${fp}, FN ${fn}, TN ${tn} · assumed weighted error ${fmt(fp+cost*fn)}. Changing the threshold changes classifications, not fitted probabilities.`;status('Retrospective score only. Model promotion is withheld; these are revised-data probabilities.');draw(rows.map(r=>({date:r.date,target:Number(r.y),probability:Number(r[key]),signal:Number(r[key])>=threshold?'Review':'No alert',last_training_label:r.last_training_label})));}
function restaurant(){if(!Array.isArray(DATA.rows)||!DATA.rows.length)throw Error('Pinned issuer evidence is missing.');const r=DATA.rows.find(x=>x.ticker===$('issuer').value);if(!r)throw Error('Selected issuer evidence is missing.');const s=num('shock',0,.8),m=num('margin',0,1,true),e=num('escalation',0,1),f=num('floor',0,.3),c=num('cap',0,.2),a=num('recovery',0,1),R=Number(r.revenue),E=Number(r.ebit),L=Number(r.lease_cost);if(!Number.isFinite(R)||R<=0||!Number.isFinite(E)||!Number.isFinite(L)||L<0)throw Error('Invalid pinned issuer facts.');const stressed=E-R*s*m-L*e,gap=Math.max(0,f*R-stressed),caps=[c*R,a*s*R],benefit=[1,m],weights=[.5,.15],plan=[0,0];let left=gap;for(const k of [0,1].sort((i,j)=>weights[i]/benefit[i]-weights[j]/benefit[j]||i-j)){plan[k]=Math.min(caps[k],left/benefit[k]);left=Math.max(0,left-plan[k]*benefit[k]);}const feasible=gap<=caps[0]+m*caps[1]+1e-6;$('result-value').textContent=money(stressed);$('result-detail').textContent=feasible?`Conditional plan feasible. Gap to floor ${money(gap)}; cost savings ${money(plan[0])}; recovered sales ${money(plan[1])}; assumed response resource ${money(.5*plan[0]+.15*plan[1])}.`:`No feasible plan under these caps. Gap to floor ${money(gap)}; uncovered gap after full capacity ${money(Math.max(0,left))}.`;status('Fiscal year ending '+r.end+'. Lease expense is already included in EBIT; only incremental lease escalation is deducted. This is earnings stress, not a liquidity or covenant test.');draw(DATA.scenarios.filter(x=>x.ticker===r.ticker));}
$('calculate').addEventListener('click',calculate);$('scenario-form').addEventListener('submit',e=>{e.preventDefault();calculate();});$('reset').addEventListener('click',()=>{for(const [id,v] of Object.entries(initial))$(id).value=v;calculate();$('evidence-scroll').scrollLeft=0;document.querySelector('input,select').focus();});$('search').addEventListener('input',()=>draw(visible));calculate();
'''
def escape(x):return html.escape(str(x))
def table(rows,fields=None,bodyid=''):
 if not rows:return '<p>No retained observations.</p>'
 fields=fields or list(rows[0]);thead=''.join('<th scope="col">'+escape(k.replace('_',' '))+'</th>' for k in fields)
 body=''.join('<tr>'+''.join('<td>'+escape(f'{r[k]:,.4f}' if isinstance(r[k],float) else r[k])+'</td>' for k in fields)+'</tr>' for r in rows)
 return '<div class="scroll" tabindex="0" aria-label="Scrollable evidence table" id="evidence-scroll"><table><thead><tr>'+thead+'</tr></thead><tbody'+(' id="'+bodyid+'"' if bodyid else '')+'>'+body+'</tbody></table></div>'
def shell(title,subtitle,content):return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><style>'+STYLE+'</style></head><body><header><div class="eyebrow">Prathamesh Singh · independent finance research</div><h1>'+title+'</h1><p>'+subtitle+'</p></header><main>'+content+'</main><footer>Research prototype · source cutoff October 26, 2026 · offline application · results do not establish causal effects or authorize a financial decision.</footer></body></html>'
def kpis(items):return '<div class="kpis">'+''.join('<div class="metric"><strong>'+escape(a)+'</strong><span>'+escape(b)+'</span></div>' for a,b in items)+'</div>'
def control(id,label,val,lo,hi,step='any',type='number'):
 return '<label for="'+id+'">'+label+'<input id="'+id+'" data-name="'+label+'" type="'+type+'" value="'+str(val)+'" min="'+str(lo)+'" max="'+str(hi)+'" step="'+str(step)+'"></label>'
def select(id,label,items):return '<label for="'+id+'">'+label+'<div class="select-bound"><select id="'+id+'" aria-label="'+label+'">'+''.join('<option value="'+escape(v)+'">'+escape(t)+'</option>' for v,t in items)+'</select></div></label>'
def bars(title,labels,values,unit):
 top=max(values)*1.12;rows=''
 for i,(lab,v) in enumerate(zip(labels,values)):
  y=65+i*47;rows+=f'<text x="16" y="{y+18}" font-size="14">{escape(lab)}</text><rect x="210" y="{y}" width="{v/top*420:.2f}" height="25" fill="#71549f"/><text x="660" y="{y+18}" font-size="14">{v:.4f}</text>'
 return f'<svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="{escape(title)}" viewBox="0 0 800 {100+47*len(values)}"><title>{escape(title)}</title><rect width="800" height="100%" fill="white"/><text x="16" y="30" font-family="sans-serif" font-size="19">{escape(title)}</text><g font-family="sans-serif" fill="#242137">{rows}</g><text x="16" y="{87+47*len(values)}" font-size="12">{escape(unit)}</text></svg>'
def build():
 for slug in [CREDIT,REST]:
  root=ROOT/slug;o=root/'outputs';m=json.loads((o/'metrics.json').read_text());iscredit=slug==CREDIT
  if iscredit:
   title='Credit Spread Recession Signal Audit';subtitle='Does adding credit spreads improve a yield-curve baseline? Revised monthly history, 1970–2024; evaluation origins 2008–2023.'
   finding=f"Across {m['test_months']} test months, candidate Brier loss is {m['candidate']['brier']:.4f}, versus {m['curve_baseline']['brier']:.4f} for the curve model and {m['expanding_unconditional']['brier']:.4f} for the unconditional baseline. Lower is better."
   action='Retain the simple unconditional benchmark. The credit model improves on the curve model here but fails to beat the unconditional benchmark. Its block interval crosses zero and only two distinct positive target runs occur. Withhold predictive promotion.'
   items=[('192 test months','12-month overlapping outcomes'),('2 target runs','few independent crisis episodes'),('Promotion withheld','revised vintages; no live forecasting')]
   chart=bars('Held-out Brier loss · lower is better',['Unconditional','Curve only','Curve + credit'],[m['expanding_unconditional']['brier'],m['curve_baseline']['brier'],m['candidate']['brier']],'Frozen model-selection window; expanding fits; 2008–2023 origins.');fields=['date','target','probability','signal','last training label'];rows=readcsv((o/'test_predictions.csv'));data={'kind':'credit','rows':rows}
   controls=select('model','Historical model',[('candidate_probability','Curve + credit'),('curve_probability','Curve only'),('unconditional','Expanding unconditional')])+control('threshold','Review probability threshold',m['threshold_5_to_1'],.05,.95,.05)+control('fncost','Assumed missed-alert cost',5,1,20,1)+control('start','Start origin month','2008-01','2008-01','2023-12',1,'month')+control('end','End origin month','2023-12','2008-01','2023-12',1,'month')
   label='Historical Brier loss';limits='NBER turning points are dated retrospectively. A twelve-month label gap does not recreate actual announcement availability. FRED history is revised, not ALFRED vintage data. BAA/10-year spreads retain a maturity mismatch and incorporate liquidity and risk-premium effects. The positive-target runs and monthly outcomes are dependent; block bands describe historical resampling, not guaranteed future coverage. False-alert costs are assumptions.'
   observed=[{'model':'Unconditional','Brier':round(m['expanding_unconditional']['brier'],6),'AUROC':round(m['expanding_unconditional']['roc_auc'],4)},{'model':'Curve only','Brier':round(m['curve_baseline']['brier'],6),'AUROC':round(m['curve_baseline']['roc_auc'],4)},{'model':'Curve + credit','Brier':round(m['candidate']['brier'],6),'AUROC':round(m['candidate']['roc_auc'],4)}]
   detail=f"Candidate minus curve Brier difference: {m['delta_brier']:.5f}; 24-month circular-block interval [{m['delta_brier_block24_interval'][0]:.5f}, {m['delta_brier_block24_interval'][1]:.5f}]. At the calibration-selected threshold of {m['threshold_5_to_1']:.2f}, the candidate produces {m['candidate']['fp']} false alerts and {m['candidate']['fn']} missed positive months. These are overlapping months, not independent event counts."
  else:
   title='Restaurant Lease & Operating Leverage';subtitle='A finance-committee review of earnings resilience and conditional response capacity. Six issuers; dated fiscal-year 2025 base.'
   finding=f"The retained panel contains {m['issuer_years']} issuer-years. Latest annual operating lease cost totals ${m['latest_operating_lease_cost']/1e9:.3f}B, compared with ${m['latest_operating_lease_cash']/1e9:.3f}B of reported operating lease payments. These are different accounting measures."
   action=f"Prioritize operational diligence where the conditional response frontier is insufficient. {m['infeasible']} of {m['scenarios']} assumed scenarios remain infeasible; {m['combined_only_feasible']} are feasible only when both response levers are available. No actual turnaround benefits are measured."
   items=[('32 issuer-years','uneven retained annual coverage'),('216 stress cases','independent LP reconciliation'),('32 infeasible cases','under the stated caps and floors')]
   latest=readcsv((o/'latest.csv'));numeric=['revenue','ebit','lease_cost','lease_cash'];
   for r in latest:
    for k in numeric:r[k]=float(r[k])
   chart=bars('FY2025 operating lease expense / revenue',[r['ticker'] for r in latest],[100*float(r['lease_cost_share']) for r in latest],'Percent; consolidated historical accounting measure, not a peer valuation ranking.');scenarios=readcsv((o/'scenario_frontier.csv'));view=[{k:r[k] for k in ['ticker','shock','contribution_margin','lease_escalation','ebit_floor','feasible','remaining_gap_after_full_capacity']} for r in scenarios];data={'kind':'restaurant','rows':latest,'scenarios':view}
   fields=list(view[0]);controls=select('issuer','Issuer evidence',[(r['ticker'],r['ticker']+' · '+r['end']) for r in latest])+control('shock','Revenue decline fraction',.1,0,.8)+control('margin','Lost-sales contribution margin',.35,0,1)+control('escalation','Incremental lease escalation',.1,0,1)+control('floor','Target EBIT / base revenue',.03,0,.3)+control('cap','Cost-savings cap / base revenue',.02,0,.2)+control('recovery','Recoverable share of lost sales',.5,0,1)
   label='Stressed operating earnings · USD';limits='Annual fiscal ends differ; coverage is uneven. EBIT includes depreciation and lease expense, impairments and other operating items. Lease-cost scope and cash-payment scope can differ, and consolidation/acquisitions change comparability. No store-level contribution margins, implementation costs, elasticities, landlord concessions, current liquidity or lender covenants are observed. The response weights and capacity caps are assumed. A mathematical optimum does not establish that management can execute it.'
   observed=[{'issuer':r['ticker'],'fiscal_end':r['end'],'EBIT_margin':round(float(r['ebit_margin']),4),'lease_expense':int(r['lease_cost']),'lease_cash':int(r['lease_cash'])} for r in latest];detail='Earnings after stress = reported EBIT − revenue × decline × assumed contribution margin − lease expense × incremental escalation. Base rent is already in EBIT and is not deducted again. The response frontier minimizes assumed resource cost of capped savings and recovered sales; it does not optimize layoffs, closures or rent defaults.'
  (o/'chart.svg').write_text(chart+'\n')
  brief='<section class="card"><h2>Decision brief</h2><p>'+finding+'</p><div class="note">'+action+'</div>'+kpis(items)+'</section>'
  report=brief+'<section class="card"><h2>Observed evidence</h2>'+chart+table(observed)+'</section><section class="card"><h2>How the decision is bounded</h2><p>'+detail+'</p><p>'+limits+'</p><p><a href="../EXECUTIVE_BRIEF.md">Executive brief</a> · <a href="../METHODS.md">Methods and assumptions</a> · <a href="../INTERVIEW.md">Resume evidence and interview answers</a></p><a href="app.html">Open offline workbench</a></section>'
  (o/'report.html').write_text(shell(title,subtitle,report)+'\n')
  empty=[{k:'' for k in fields}];app=brief+'<section class="card"><span class="badge">Scenario controls are assumptions; model evidence is historical</span><h2>Analyst workbench</h2><form id="scenario-form" novalidate><div class="controls">'+controls+'</div><button type="submit" id="calculate">Calculate</button><button type="button" class="secondary" id="reset">Reset</button></form><div id="status" role="status" aria-live="polite"></div><div class="metric"><span>'+label+'</span><strong id="result-value"></strong></div><p id="result-detail"></p></section><section class="card"><h2>Inspect the evidence</h2><label for="search">Search evidence</label><input id="search" type="search" placeholder="Try a year, issuer or field"><p id="row-count" class="muted"></p>'+table(empty,fields,bodyid='evidence-body')+'</section><section class="card"><h2>Interpretation limits</h2><p>'+limits+'</p><a href="report.html">Read executive report</a></section><script>const DATA='+json.dumps(data,separators=(',',':')).replace('</','<\\/')+';window.RESEARCH_DATA=DATA;</script><script>'+JS+'</script>'
  (o/'app.html').write_text(shell(title,subtitle,app)+'\n')
if __name__=='__main__':build()
